import styles from './SeasonCard.module.scss'
import { Col } from 'react-bootstrap'
import PropTypes from 'prop-types'
import noImage from '../../../assets/no-image.png'

const SeasonCard = ({ season }) => {
  return (
    <Col xs="12" sm="6" md="3" lg="2" className="mb-4">
      <div
        className={styles.card}
        
      >
        <div
        className={styles.img}
        style={{
          backgroundImage: `url(${season.season_cover || noImage})`,
        }}
      ></div>
        <div className={styles.top}>
          <p>{"Sequential number of the season: " + season.season_number}</p>
          <p>{"Title: " + season.title}</p>
          <p>{"Number of episodes: " + season.episodes_count}</p>
          <p>{"Rating: " + season.rating}</p>
          <p>{"Year of release: " + season.year}</p>
          <p>{"Official release date: " + season.release_date}</p>
          <p>{"Optional notes about the season: " + season.notes}</p>
        </div>
      </div>
    </Col>
  )
}

SeasonCard.propTypes = {
  anime: PropTypes.object.isRequired,
}

export default SeasonCard;